use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn generate_specific_trait (category : & str , output : & str) -> Result < () > { println ! ("🔧 Generating {} trait..." , category) ; let generator = SyscallDecouplingGenerator :: new () ; let template = generator . generate_decoupling_template () ; let matching_trait = template . syscall_traits . iter () . find (| t | t . name . to_lowercase () . contains (& category . to_lowercase ())) ; if let Some (trait_def) = matching_trait { let rust_code = generator . generate_trait_code (trait_def) ; let formatted_code = format ! ("// Generated {} trait for syscall decoupling\n\n{}" , trait_def . name , rust_code . to_string ()) ; std :: fs :: write (output , formatted_code) ? ; println ! ("✅ Generated {} trait: {}" , trait_def . name , output) ; println ! ("   Methods: {}" , trait_def . methods . len ()) ; println ! ("   Safety: {:?}" , trait_def . safety_level) ; } else { println ! ("❌ Unknown trait category: {}" , category) ; println ! ("Available categories: filesystem, process, environment, io, network, memory, time") ; } Ok (()) }
}